style.css:
@-moz-document domain("youtube.com") {
:root {
        --olive: #6B7A45;
        --olive-light: #87995B;
        --coffee: #B68A63;
        --latte: #D7C2A3;
        --cream: #F5F0E8;
        --dark: #2E2B27;
    }

    /* 1. Cambiar el fondo general y el texto de YouTube */
    ytd-app, 
    body, 
    #contentContainer,
    #page-manager,
    ytd-browse,
    ytd-watch-flexy {
        background-color: var(--dark) !important;
    }

    /* Textos principales a color crema */
    yt-formatted-string,
    span,
    h1, h2, h3,
    #video-title {
        color: var(--cream) !important;
    }

    /* Barra superior de búsqueda y botones laterales */
    #masthead-container,
    #background.ytd-masthead {
        background-color: var(--dark) !important;
    }

    #search-form #container {
        background-color: var(--olive) !important;
        border: 1px solid var(--coffee) !important;
    }

    #search-icon-legacy {
        background-color: var(--coffee) !important;
        border: none !important;
    }

    /* 2. PERSONALIZACIÓN DE LA BARRA DE REPRODUCCIÓN (El Ovillo) */
    .ytp-play-progress {
        background: var(--olive-light) !important;
    }

    .ytp-load-progress, .ytp-progress-list {
        background: var(--coffee) !important;
        opacity: 0.6;
    }

    .ytp-scrubber-button {
        background: radial-gradient(circle, var(--latte) 20%, var(--olive) 21%, var(--olive) 40%, var(--latte) 41%, var(--coffee) 60%, var(--cream) 61%) !important;
        border: 2px solid var(--cream) !important;
        border-radius: 50% !important;
        box-shadow: 0 0 5px rgba(0,0,0,0.5), inset 0 0 4px rgba(0,0,0,0.3) !important;
        transform: scale(1.4) !important;
    }

    .ytp-progress-bar-container:hover .ytp-scrubber-button {
        transform: scale(1.6) rotate(35deg) !important;
        transition: transform 0.2s ease;
    }
}
